# Public Reproduction

From `app/tasks/task_006/` or from the prepared agent workspace:

```bash
python reproduce.py
```

The script builds the local BEDTools source if needed, runs a small interval
enrichment workflow twice, and writes:

```text
outputs/reproduction_report.json
```

The public workflow first uses a compact database/background interval set, then
uses an augmented background set with additional valid intervals that cannot
overlap the query. These appended intervals should not change the observed
overlap count, but they should still be reflected in the Fisher exact test's
statistical background. The report intentionally does not provide a full
corrected Fisher table or private expected outputs.

The public reproduction intentionally observes only the command's scientific
output. It does not inspect source text or require a particular finalization
strategy. The implementation may preserve the same behavior through different
scanner, context, or command-level designs; the private verifier exercises
those general cases.
Inspect the BEDTools source tree and the public reproduction workflow. A small genomic interval-enrichment analysis becomes unstable when the database/background interval set is augmented with valid intervals that cannot overlap the query intervals.

Those appended background intervals should not create new observed overlaps, but they are still part of the statistical sample used by the Fisher exact test table. Repair the implementation so that interval-enrichment output uses complete summary state for valid BED and genome inputs. The fix should preserve the behavior of ordinary interval-overlap commands and should not hard-code the public fixture, file names, chromosome names, counts, p-values, or coordinates.

Run `python reproduce.py` from this task directory to build the local source and reproduce the public failure.
/*
 * fisher.h
 *
 *  Created on: Apr 30, 2015
 *      Author: nek3d
 */

#ifndef FISHER_H_
#define FISHER_H_

#include "jaccard.h"
#include "bedFile.h"
#include "ContextFisher.h"
#include "kfunc.h"

class Fisher : public Jaccard {
public:
    Fisher(ContextFisher *context);
    bool init();
    bool finalizeCalculations();
    void giveFinalReport(RecordOutputMgr *outputMgr);

protected:
    bool _haveExclude;
    unsigned long _queryCounts;
    unsigned long _dbCounts;
    unsigned long _overlapCounts;
    vector<int> _qsizes;
    BedFile *_excludeFile;
    unsigned long getTotalIntersection(RecordKeyVector &hits);
    virtual ContextFisher *upCast(ContextBase *context) { return static_cast<ContextFisher *>(context); }

};



#endif /* FISHER_H_ */
/*
 * fisher.cpp
 *
 *  Created on: Apr 30, 2015
 *      Author: nek3d
 */

#include "fisher.h"

Fisher::Fisher(ContextFisher *context)
: Jaccard(context),
  _haveExclude(false),
  _queryCounts(0),
  _dbCounts(0),
  _overlapCounts(0),
  _excludeFile(NULL)

{
}

bool Fisher::init(void)
{
	if(!(upCast(_context)->getExcludeFile().empty())){
		string ex = upCast(_context)->getExcludeFile();
		_excludeFile = new BedFile(ex);
		_excludeFile->loadBedFileIntoMergedMap();
		_haveExclude = true;
	}
	return Jaccard::init();
}

bool Fisher::finalizeCalculations()
{
    _sweep->closeOut();
    _queryUnion = _sweep->getQueryTotalRecordLength();
    _dbUnion = _sweep->getDatabaseTotalRecordLength();

    _queryCounts = _sweep->getQueryTotalRecords();
    _dbCounts = _sweep->getDatabaseTotalRecords();

    _unionVal = _queryUnion + _dbUnion;
    return true;
}

void Fisher::giveFinalReport(RecordOutputMgr *outputMgr)
{
    double left, right, two;

    long long genomeSize = _context->getGenomeFile()->getGenomeSize();
    if(_haveExclude){
        genomeSize -= _excludeFile->getTotalFlattenedLength();
    }
    // bases covered by neither
    long long n22_full_bases = genomeSize;
    //long long n22_bases = genomeSize - _queryUnion - _dbUnion + _intersectionVal;
    long double dMean = 1.0 + _dbUnion / (long double)_dbCounts;
    long double qMean = 1.0 + _queryUnion / (long double)_queryCounts;

    // heursitic, but seems to work quite well -- better than doing more intuitive sum then divide.
    long double bMean = (qMean + dMean);
    //bMean = (_unionVal + 2.0 * _intersectionVal) / (long double)(_dbCounts + _queryCounts);

    long long n11 = (long)_overlapCounts;
    // this could be < 0 because multiple overlaps
    long long n12 = (long)max(0L, (long)_queryCounts - (long)_overlapCounts);
    long long n21 = max(0L, (long)(_dbCounts - _overlapCounts));
    long long n22_full = max(n21 + n12 + n11, (long long)(n22_full_bases / bMean));
    long long n22 = max(0L, (long)(n22_full - n12 - n21 - n11));

    printf("# Number of query intervals: %lu\n", _queryCounts);
    printf("# Number of db intervals: %lu\n", _dbCounts);
    printf("# Number of overlaps: %lu\n", _overlapCounts);
    printf("# Number of possible intervals (estimated): %lld\n", n22_full);

    printf("# phyper(%lld - 1, %lu, %lld - %lu, %lu, lower.tail=F)\n", n11, _queryCounts, n22_full, _queryCounts, _dbCounts);
    cout << "# Contingency Table Of Counts" << endl;
    printf("#_________________________________________\n");
    printf("#           | %-12s | %-12s |\n", " in -b", "not in -b");
    printf("#     in -a | %-12lld | %-12lld |\n", n11, n12);
    printf("# not in -a | %-12lld | %-12lld |\n", n21, n22);
    printf("#_________________________________________\n");

    kt_fisher_exact(n11, n12, n21, n22, &left, &right, &two);
    double ratio = ((double)n11 / (double)n12) / ((double)n21 / (double)n22);

    printf("# p-values for fisher's exact test\n");
    printf("left\tright\ttwo-tail\tratio\n");

    /* Some implementations report NAN as negative, some as positive. To ensure
     * we get consistent output from each compiler, we should do our own test.
     * Since the test script assumes "-nan", let's setle on that.
     */
    if(std::isnan(ratio)) {
        printf("%.5g\t%.5g\t%.5g\t-nan\n", left, right, two);
    } else {
        printf("%.5g\t%.5g\t%.5g\t%.3f\n", left, right, two, ratio);
    }
}

unsigned long Fisher::getTotalIntersection(RecordKeyVector &recList)
{
    unsigned long intersection = 0;
    Record *key = recList.getKey();
    CHRPOS keyStart = key->getStartPos();
    CHRPOS keyEnd = key->getEndPos();

    _overlapCounts += recList.size();
    // note that we truncate to a max size of 2.1GB
    _qsizes.push_back((int)(keyEnd - keyStart));

    int hitIdx = 0;
    for (RecordKeyVector::iterator_type iter = recList.begin(); iter != recList.end(); iter = recList.next()) {
        CHRPOS maxStart = max((*iter)->getStartPos(), keyStart);
        CHRPOS minEnd = min((*iter)->getEndPos(), keyEnd);
        _qsizes.push_back((int)(minEnd - maxStart));
        if (_context->getObeySplits()) {
            intersection += upCast(_context)->getSplitBlockInfo()->getOverlapBases(hitIdx);
            hitIdx++;
        } else {
            intersection += (unsigned long)(minEnd - maxStart);
        }
    }
    _numIntersections += (int)recList.size();
    return intersection;
}
/*
 * ContextFisher.cpp
 *
 */

#include "ContextFisher.h"

ContextFisher::ContextFisher() {
	setSortedInput(true);
	setUseMergedIntervals(false); //by default,
	//intervals are merged in Jaccard, but unmerged in fisher.
}

ContextFisher::~ContextFisher() {
} 
bool ContextFisher::parseCmdArgs(int argc, char **argv, int skipFirstArgs)
{
	for (_i=_skipFirstArgs; _i < argc; _i++) {
		if (isUsed(_i - _skipFirstArgs)) {
			continue;
		}
		else if (strcmp(_argv[_i], "-exclude") == 0) {
			if (!handle_exclude()) return false;
		}
		else if (strcmp(_argv[_i], "-m") == 0) {
			if (!handle_m()) return false;
		}

	}
	return ContextIntersect::parseCmdArgs(argc, argv, _skipFirstArgs);
}

bool ContextFisher::isValidState()
{
	if (!ContextJaccard::isValidState()) {
		return false;
	}
    if (_genomeFile == NULL){
        _errorMsg = "\nERROR*****: specify -g genome file*****\n";
        return false;
    }
	return true;
}

bool ContextFisher::handle_exclude()
{
    if (_argc <= _i+1) {
        _errorMsg = "\n***** ERROR: -exclude option given, but no file specified. *****";
        return false;
    }

    do {
        markUsed(_i - _skipFirstArgs);
        _i++;
        markUsed(_i - _skipFirstArgs);
    } while (_argc > _i+1 && _argv[_i+1][0] != '-');
    setExcludeFile(string(_argv[_i]));
    return true;
}

bool ContextFisher::handle_m()
{
	setUseMergedIntervals(true);
    markUsed(_i - _skipFirstArgs);
    _i++;
	return true;
}

